function syncMaskRegions(){
  var study=document.body.classList.contains('study');
  document.querySelectorAll('.mask[data-disclosure]').forEach(function(mask){
    var btn=mask.querySelector('.mask-toggle'), region=mask.querySelector('.mask-region');
    if(!btn||!region) return;
    var open=!study || mask.dataset.revealed==='1';
    region.hidden=false;
    region.setAttribute('aria-hidden',open?'false':'true');
    region.inert=!open;
    mask.classList.toggle('shown',mask.dataset.revealed==='1');
    btn.setAttribute('aria-expanded',open?'true':'false');
    btn.textContent=open?'Hide answer':'Reveal answer';
  });
}

